import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [activeTab, setActiveTab] = useState('signup');
  const [signupData, setSignupData] = useState({ name: '', email: '', password: '', confirm: '' });
  const [loginData, setLoginData] = useState({ email: '', password: '' });
  const [strength, setStrength] = useState('');

  const switchTab = (tab) => setActiveTab(tab);

  const checkStrength = (password) => {
    if (password.length >= 8 && /[A-Z]/.test(password) && /\d/.test(password)) return 'strong';
    if (password.length >= 6) return 'medium';
    return 'weak';
  };

  const handleSignupChange = (e) => {
    const { name, value } = e.target;
    setSignupData((prev) => ({ ...prev, [name]: value }));

    if (name === 'password') setStrength(checkStrength(value));
  };

  const handleLoginChange = (e) => {
    const { name, value } = e.target;
    setLoginData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSignupSubmit = async (e) => {
    e.preventDefault();
    if (signupData.password !== signupData.confirm) return alert('Passwords do not match');
    try {
      const res = await axios.post('http://localhost:5000/api/signup', signupData);
      alert(res.data.message || 'Signup successful');
    } catch (err) {
      alert(err.response?.data?.message || 'Signup failed');
    }
  };

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/login', loginData);
      alert(res.data.message || 'Login successful');
    } catch (err) {
      alert(err.response?.data?.message || 'Login failed');
    }
  };

  return (
    <div className="container">
      <div className="tabs">
        <div className={`tab ${activeTab === 'signup' ? 'active' : ''}`} onClick={() => switchTab('signup')}>Sign Up</div>
        <div className={`tab ${activeTab === 'login' ? 'active' : ''}`} onClick={() => switchTab('login')}>Login</div>
      </div>

      {activeTab === 'signup' && (
        <form onSubmit={handleSignupSubmit}>
          <input type="text" name="name" placeholder="Full Name" required onChange={handleSignupChange} />
          <input type="email" name="email" placeholder="Email" required onChange={handleSignupChange} />
          <input type="password" name="password" placeholder="Password" required onChange={handleSignupChange} />
          <input type="password" name="confirm" placeholder="Confirm Password" required onChange={handleSignupChange} />
          <div className={`strength-${strength}`}>Strength: {strength}</div>
          <button type="submit">Sign Up</button>
        </form>
      )}

      {activeTab === 'login' && (
        <form onSubmit={handleLoginSubmit}>
          <input type="email" name="email" placeholder="Email" required onChange={handleLoginChange} />
          <input type="password" name="password" placeholder="Password" required onChange={handleLoginChange} />
          <button type="submit">Login</button>
        </form>
      )}
    </div>
  );
}

export default App;
